// ========== TikaInputStream-specific Methods ==========
public int peek(byte[] buffer) throws IOException {
    int n = 0;
    mark(buffer.length);
    int m = read(buffer);
    while (m != -1) {
        n += m;
        if (n < buffer.length) {
            m = read(buffer, n, buffer.length - n);
        } else {
            m = -1;
        }
    }
    reset();
    return n;
}
